args.command:
cat > /root/.nanobot/workspace/breakout.html << 'HTMLEOF'
<!DOCTYPE html>
<html lang="en"><head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Neon Breakout</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#0a0a0f;display:flex;justify-content:center;align-items:center;min-height:100vh;overflow:hidden;font-family:"Courier New",monospace;touch-action:none;user-select:none}
canvas{border:2px solid #0ff;box-shadow:0 0 30px #0ff,0 0 60px #0ff3,inset 0 0 30px #0ff2;border-radius:8px}
#ui{position:fixed;top:20px;left:50%;transform:translateX(-50%);color:#0ff;font-size:18px;text-shadow:0 0 10px #0ff,0 0 20px #0ff;z-index:10;display:flex;gap:30px}
#ui span{color:#f0f}
#msg{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);color:#0ff;font-size:36px;text-shadow:0 0 20px #0ff,0 0 40px #0ff;z-index:20;display:none;text-align:center}
#combo{position:fixed;top:70px;left:50%;transform:translateX(-50%);color:#ff0;font-size:24px;text-shadow:0 0 15px #ff0;z-index:10;opacity:0;transition:opacity 0.3s}
</style></head><body>
<div id="ui">SCORE: <span id="sc">0</span> &nbsp; LIVES: <span id="lv">3</span> &nbsp; LEVEL: <span id="ll">1</span></div>
<div id="combo"></div>
<div id="msg"></div>
<canvas id="c"></canvas>
<script>
const C=document.getElementById("c"),X=C.getContext("2d");
C.width=800;C.height=600;
const W=C.width,H=C.height;
let score=0,lives=3,level=1,combo=0,comboTimer=0,running=false,gameOver=false,paused=false;
const colors=["#f0f","#60f","#0ff","#0f0","#ff0","#f80","#f00"];
let bricks=[],particles=[],stars=[];
const pad={w:120,h:14,x:W/2-60,y:H-40,speed:8,color:"#0ff"};
const ball={x:W/2,y:H-60,r:8,dx:0,dy:0,speed:5,trail:[]};
const keys={};
document.addEventListener("keydown",e=>{
  keys[e.key]=true;
  if(e.key===" "){
    if(gameOver||!running){startGame()}
    else if(running){paused=!paused}
  }
  if(e.key==="p"||e.key==="P")paused=!paused;
});
document.addEventListener("keyup",e=>keys[e.key]=false);
C.addEventListener("mousemove",e=>{const r=C.getBoundingClientRect();pad.x=e.clientX-r.left-pad.w/2});
C.addEventListener("touchmove",e=>{e.preventDefault();const r=C.getBoundingClientRect();pad.x=e.touches[0].clientX-r.left-pad.w/2},{passive:false});
C.addEventListener("touchstart",e=>{
  e.preventDefault();
  if(gameOver||!running)startGame();
  else paused=!paused;
},{passive:false});

function initStars(){stars=[];for(let i=0;i<100;i++)stars.push({x:Math.random()*W,y:Math.random()*H,r:Math.random()*1.5+0.5,a:Math.random(),s:Math.random()*0.02+0.005})}
function initBricks(){
  bricks=[];
  const rows=5+Math.min(level-1,4),cols=10,bw=70,bh=22,pad=6,ox=(W-cols*(bw+pad)+pad)/2,oy=60;
  for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
    const hp=r<2&&level>2?2:1;
    bricks.push({x:ox+c*(bw+pad),y:oy+r*(bh+pad),w:bw,h:bh,color:colors[r%colors.length],alive:true,hp,maxHp:hp,glow:0});
  }
}
function resetBall(){
  ball.x=W/2;ball.y=H-60;
  const angle=(Math.random()*0.6+0.2)*Math.PI*(Math.random()>0.5?1:-1);
  ball.dx=Math.sin(angle)*ball.speed;
  ball.dy=-Math.abs(Math.cos(angle))*ball.speed;
  ball.trail=[];
}
function startGame(){
  score=0;lives=3;level=1;combo=0;gameOver=false;paused=false;running=true;
  ball.speed=5;
  initBricks();resetBall();
  document.getElementById("msg").style.display="none";updateUI();
}
function updateUI(){document.getElementById("sc").textContent=score;document.getElementById("lv").textContent=lives;document.getElementById("ll").textContent=level}
function spawnParticles(x,y,color,n=12){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=Math.random()*4+1;particles.push({x,y,dx:Math.cos(a)*s,dy:Math.sin(a)*s,life:1,color,r:Math.random()*3+1})}}
function showMsg(t){const m=document.getElementById("msg");m.innerHTML=t;m.style.display="block"}
function showCombo(c){const el=document.getElementById("combo");el.textContent=c+"x COMBO!";el.style.opacity=1;comboTimer=60}
function nextLevel(){level++;ball.speed=Math.min(ball.speed+0.5,12);combo=0;initBricks();resetBall();updateUI()}

function clampBall(){
  if(ball.x-ball.r<0){ball.x=ball.r;ball.dx=Math.abs(ball.dx)}
  if(ball.x+ball.r>W){ball.x=W-ball.r;ball.dx=-Math.abs(ball.dx)}
  if(ball.y-ball.r<0){ball.y=ball.r;ball.dy=Math.abs(ball.dy)}
}

function collideBricks(){
  for(let b of bricks){
    if(!b.alive)continue;
    const cx=Math.max(b.x,Math.min(ball.x,b.x+b.w));
    const cy=Math.max(b.y,Math.min(ball.y,b.y+b.h));
    const dx=ball.x-cx,dy=ball.y-cy;
    const dist=Math.sqrt(dx*dx+dy*dy);
    if(dist<ball.r){
      b.hp--;
      if(b.hp<=0){
        b.alive=false;combo++;
        if(combo>1)showCombo(combo);
        score+=10*combo;
        spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,15);
      }else{
        spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,6);
      }
      if(dist===0){ball.dy*=-1}
      else{
        const nx=dx/dist,ny=dy/dist;
        const dot=ball.dx*nx+ball.dy*ny;
        ball.dx-=2*dot*nx;ball.dy-=2*dot*ny;
        const overlap=ball.r-dist;
        ball.x+=nx*overlap;ball.y+=ny*overlap;
      }
      updateUI();return;
    }
  }
}

function update(){
  if(!running||gameOver||paused)return;
  if(keys["ArrowLeft"]||keys["a"])pad.x-=pad.speed;
  if(keys["ArrowRight"]||keys["d"])pad.x+=pad.speed;
  pad.x=Math.max(0,Math.min(W-pad.w,pad.x));

  ball.trail.push({x:ball.x,y:ball.y,a:1});if(ball.trail.length>15)ball.trail.shift();
  ball.trail.forEach(t=>t.a*=0.9);

  const steps=Math.ceil(ball.speed/4);
  const sdx=ball.dx/steps,sdy=ball.dy/steps;
  for(let s=0;s<steps;s++){
    ball.x+=sdx;ball.y+=sdy;
    clampBall();
    collideBricks();
    if(bricks.every(b=>!b.alive)){nextLevel();return}
  }

  if(ball.y+ball.r>H){
    lives--;combo=0;updateUI();
    if(lives<=0){gameOver=true;running=false;showMsg("GAME OVER<br><small style='font-size:16px'>Press SPACE to restart</small>")}
    else resetBall();
    return;
  }

  if(ball.dy>0&&ball.y+ball.r>=pad.y&&ball.y+ball.r<=pad.y+pad.h+ball.dy&&ball.x>=pad.x-ball.r&&ball.x<=pad.x+pad.w+ball.r){
    const hit=Math.max(0,Math.min(1,(ball.x-pad.x)/pad.w));
    const angle=(hit-0.5)*Math.PI*0.7;
    ball.dx=Math.sin(angle)*ball.speed;
    ball.dy=-Math.abs(Math.cos(angle)*ball.speed);
    ball.y=pad.y-ball.r;
    spawnParticles(ball.x,ball.y,"#0ff",6);
  }

  particles.forEach(p=>{p.x+=p.dx;p.y+=p.dy;p.dy+=0.05;p.life-=0.02});
  particles=particles.filter(p=>p.life>0);
  if(comboTimer>0){comboTimer--;if(comboTimer<=0)document.getElementById("combo").style.opacity=0}
  stars.forEach(s=>{s.a+=s.s;if(s.a>1||s.a<0)s.s*=-1});
}

function draw(){
  X.fillStyle="#0a0a0f";X.fillRect(0,0,W,H);
  stars.forEach(s=>{X.globalAlpha=Math.abs(s.a)*0.6;X.fillStyle="#fff";X.beginPath();X.arc(s.x,s.y,s.r,0,Math.PI*2);X.fill()});
  X.globalAlpha=1;
  for(let b of bricks){if(!b.alive)continue;
    X.shadowColor=b.color;X.shadowBlur=15;
    X.fillStyle=b.color;X.fillRect(b.x,b.y,b.w,b.h);
    if(b.hp<b.maxHp){X.fillStyle="rgba(0,0,0,0.4)";X.fillRect(b.x,b.y,b.w,b.h)}
    X.shadowBlur=0;
    X.strokeStyle="rgba(255,255,255,0.3)";X.lineWidth=1;X.strokeRect(b.x+0.5,b.y+0.5,b.w-1,b.h-1)}
  ball.trail.forEach(t=>{X.globalAlpha=t.a*0.4;X.fillStyle="#0ff";X.beginPath();X.arc(t.x,t.y,ball.r*t.a,0,Math.PI*2);X.fill()});
  X.globalAlpha=1;
  X.shadowColor="#0ff";X.shadowBlur=20;
  const grd=X.createRadialGradient(ball.x,ball.y,0,ball.x,ball.y,ball.r*2);
  grd.addColorStop(0,"#fff");grd.addColorStop(0.4,"#0ff");grd.addColorStop(1,"transparent");
  X.fillStyle=grd;X.beginPath();X.arc(ball.x,ball.y,ball.r*2,0,Math.PI*2);X.fill();
  X.fillStyle="#fff";X.beginPath();X.arc(ball.x,ball.y,ball.r,0,Math.PI*2);X.fill();
  X.shadowBlur=0;
  X.shadowColor="#0ff";X.shadowBlur=15;
  const pg=X.createLinearGradient(pad.x,pad.y,pad.x+pad.w,pad.y);
  pg.addColorStop(0,"#0ff");pg.addColorStop(0.5,"#f0f");pg.addColorStop(1,"#0ff");
  X.fillStyle=pg;X.fillRect(pad.x,pad.y,pad.w,pad.h);
  X.shadowBlur=0;
  particles.forEach(p=>{X.globalAlpha=p.life;X.shadowColor=p.color;X.shadowBlur=8;X.fillStyle=p.color;X.beginPath();X.arc(p.x,p.y,p.r*p.life,0,Math.PI*2);X.fill()});
  X.globalAlpha=1;X.shadowBlur=0;
  if(paused){X.fillStyle="rgba(0,0,0,0.5)";X.fillRect(0,0,W,H);X.fillStyle="#0ff";X.font="36px Courier New";X.textAlign="center";X.shadowColor="#0ff";X.shadowBlur=20;X.fillText("PAUSED",W/2,H/2);X.shadowBlur=0}
  if(!running&&!gameOver){X.fillStyle="#0ff";X.font="24px Courier New";X.textAlign="center";X.shadowColor="#0ff";X.shadowBlur=20;X.fillText("Press SPACE to Start",W/2,H/2);X.shadowBlur=0}
}
function loop(){update();draw();requestAnimationFrame(loop)}
initStars();initBricks();loop();
</script></body></html>
HTMLEOF
echo "DONE: $(wc -l < /root/.nanobot/workspace/breakout.html) lines"
